import {mkdir,writeFile,readFile,rm,stat} from 'node:fs/promises';import path from 'node:path';import {canonicalSha256} from '../core/canonical-json.mjs';
const PROFILES={minimal:['kernel','verification'],coding:['kernel','verification','skill-intelligence','code-review-intelligence','testing','mcp'],creative:['kernel','skill-intelligence','creative-packs'],research:['kernel','research-packs','source-verification'],regulated:['kernel','verification','assurance-a4','security'],['local-small']:['kernel','verification','cli-first','low-context'],enterprise:['kernel','verification','oidc','pdp','audit','mcp']};
const safeJoin=(root,relative)=>{const full=path.resolve(root,relative);if(full!==path.resolve(root)&&!full.startsWith(`${path.resolve(root)}${path.sep}`))throw new Error('Profile path escapes target root');return full;};
export function compileHarnessProfile({profile,target,capabilities={}}={}){const components=PROFILES[profile];if(!components)throw new TypeError(`Unknown ForgeOS profile: ${profile}`);const filtered=components.filter(x=>x!=='mcp'||capabilities.mcp!==false);const files=[`.forgeos/profiles/${profile}.json`,`.forgeos/targets/${target}.json`,`.forgeos/managed.json`];const permissionDiff=[];if(filtered.includes('mcp'))permissionDiff.push({resource:'mcp',change:'enable brokered MCP tools'});if(capabilities.hooks)permissionDiff.push({resource:'hooks',change:'install event hooks'});const payload={schemaVersion:1,profile,target,components:filtered,files,permissionDiff,capabilities};return Object.freeze({...payload,planSha256:canonicalSha256(payload)});}
export async function installHarnessProfile({root,plan,principal}={}){if(principal?.type!=='human'||!principal.roles?.includes('harness-admin'))throw new Error('Human harness-admin approval is required');const records=[];for(const relative of plan.files){const full=safeJoin(root,relative);await mkdir(path.dirname(full),{recursive:true});let exists=false;try{await stat(full);exists=true;}catch{}if(exists&&relative!=='.forgeos/managed.json')continue;const content=relative.endsWith('managed.json')?JSON.stringify({planSha256:plan.planSha256},null,2):JSON.stringify({profile:plan.profile,target:plan.target,components:plan.components},null,2);await writeFile(full,content,{mode:0o600});records.push({path:relative,sha256:canonicalSha256(content)});}const installation={schemaVersion:1,planSha256:plan.planSha256,files:records.map(x=>x.path),records,installedBy:principal.id};const managed=safeJoin(root,'.forgeos/managed.json');await writeFile(managed,JSON.stringify(installation,null,2),{mode:0o600});const managedHash=canonicalSha256(JSON.stringify(installation,null,2));const index=installation.records.findIndex(x=>x.path==='.forgeos/managed.json');if(index>=0)installation.records[index]={path:'.forgeos/managed.json',sha256:managedHash};return Object.freeze({...installation,installationSha256:canonicalSha256(installation)});}
export async function uninstallHarnessProfile({root,installation,principal}={}){if(principal?.type!=='human'||!principal.roles?.includes('harness-admin'))throw new Error('Human harness-admin approval is required');for(const record of installation.records??[]){const full=safeJoin(root,record.path);let content;try{content=await readFile(full,'utf8');}catch{continue;}if(canonicalSha256(content)===record.sha256)await rm(full,{force:true});}return{status:'uninstalled'};}
